#!/usr/bin/env python3
"""Prepare isolated native goal-interpretation requests; performs no inference."""

import copy
import json
from pathlib import Path


ROOT = Path(__file__).resolve().parents[2]
MANIFEST = ROOT / "docs/audits/2026-09-04-mac-computer-use/orchestration-language-cases-sept23.json"
TEMPLATE = ROOT / ".build/repair-verification/browser-compact02-conditional-request.json"
OUTPUT = ROOT / ".build/repair-verification/native-goal-contract-prepared-01"

PROMPT = """Interpret only the complete original goal and ordered clarification answers in the user JSON. Questions supply context; answers carry user authority. Preserve every requested final outcome, information requirement, state-changing action, source constraint, prohibition, and quoted literal content. Do not replace an action with preparation or explanation. Distinguish information from actions; opening/searching/reading are information. Prohibitions are constraints, not actions; quoted content requested for entry or discussion is not an instruction to perform its contents. Keep constraints to user-stated conditions; do not invent constraints or facts. Return only the schema: concise objective, user constraints, and one requirement for each requested outcome, each labeled information or action. Do not assess completion, evidence, observations, routing, tools, or next steps. Do not omit unresolved work or infer that an action is complete."""

SCHEMA = {
    "type": "object",
    "additionalProperties": False,
    "properties": {
        "objective": {"type": "string"},
        "constraints": {
            "type": "array",
            "minItems": 0,
            "maxItems": 8,
            "items": {"type": "string"},
        },
        "requirements": {
            "type": "array",
            "minItems": 1,
            "maxItems": 8,
            "items": {
                "type": "object",
                "additionalProperties": False,
                "properties": {
                    "instruction": {"type": "string"},
                    "kind": {"type": "string", "enum": ["information", "action"]},
                },
                "required": ["instruction", "kind"],
            },
        },
    },
    "required": ["objective", "constraints", "requirements"],
}


def read_json(path: Path):
    with path.open(encoding="utf-8") as source:
        return json.load(source)


def write_json(path: Path, value) -> None:
    with path.open("w", encoding="utf-8", newline="\n") as output:
        json.dump(value, output, ensure_ascii=False, indent=2)
        output.write("\n")


def main() -> None:
    if len(PROMPT) > 1600:
        raise ValueError(f"Prompt exceeds 1600 characters: {len(PROMPT)}")

    manifest = read_json(MANIFEST)
    template = read_json(TEMPLATE)
    cases = manifest["cases"]
    if len(cases) != 6:
        raise ValueError(f"Expected six frozen cases, found {len(cases)}")

    OUTPUT.mkdir(parents=True, exist_ok=False)
    write_json(OUTPUT / "prompt-schema-spec.json", {"prompt": PROMPT, "schema": SCHEMA})
    seen_ids = set()
    for case in cases:
        case_id = case["id"]
        if case_id in seen_ids:
            raise ValueError(f"Duplicate case id: {case_id}")
        seen_ids.add(case_id)

        # Construct input from user-authored fields only. Oracle/expected fields,
        # page records, history, and other template content never enter the request.
        user_input = {"goal": case["goal"], "clarifications": case.get("clarifications", [])}
        request = copy.deepcopy(template)
        request["messages"] = [
            {"content": PROMPT, "role": "system"},
            {"content": json.dumps(user_input, ensure_ascii=False, separators=(",", ":")), "role": "user"},
        ]
